import * as React from "react";

export type FlagIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function FlagIcon({ size = 20, ...props }: FlagIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <path d="M6 21.5 L6 3.5" /><path d="M6 4.5 L18.5 4.5 L16 8.5 L18.5 12.5 L6 12.5" />
    </svg>
  );
}
